CREATE FUNCTION public.manage_client_lifecycle(target uuid, g uuid DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.otp_verified() THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF g IS NULL THEN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target AND account_type='client') OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target AND role IN ('Owner','super_admin','Admin','Trainer','Reception')) THEN RAISE EXCEPTION 'Only client-only accounts can be deactivated here'; END IF; UPDATE public.profiles SET disabled_at=coalesce(disabled_at,now()) WHERE id=target; UPDATE public.staff_invitations SET status='Cancelled' WHERE invited_user_id=target AND status='Pending'; ELSE IF NOT public.gym_access(g,'Members') OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=g AND role='Owner') THEN RAISE EXCEPTION 'Gym owner access required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.gym_records WHERE gym_id=g AND kind='members' AND client_id=target) THEN RAISE EXCEPTION 'Client does not belong to this gym'; END IF; DELETE FROM public.gym_records WHERE gym_id=g AND kind='members' AND client_id=target; DELETE FROM public.client_gym_links WHERE gym_id=g AND user_id=target; END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.manage_client_lifecycle(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_client_lifecycle(uuid,uuid) TO authenticated;